#!/usr/bin/env node
// Builds DTCG token JSON from tokens/ into:
//   dist/tokens.css          — CSS custom properties (:root primitives + semantic, .dark overrides)
//   dist/tailwind-theme.css  — Tailwind CSS v4 `@theme inline` mapping
// and refreshes the auto-generated token section of DESIGN.md (when markers exist).
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { pathToFileURL, fileURLToPath } from "node:url";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const TOKENS_DIR = join(ROOT, "tokens");
const DIST_DIR = join(ROOT, "dist");
const DESIGN_MD = join(ROOT, "DESIGN.md");

const HEADER = "<!-- Generated by scripts/build-tokens.mjs — do not edit. Source: tokens/ -->\n";

// Map semantic token keys to Tailwind color names (shadcn-compatible).
const SEMANTIC_COLORS = [
  ["background", "bg"],
  ["foreground", "fg"],
  ["card", "card"],
  ["card-foreground", "card-fg"],
  ["muted", "muted"],
  ["muted-foreground", "muted-fg"],
  ["border", "border"],
  ["input", "input"],
  ["ring", "ring"],
  ["primary", "primary"],
  ["primary-foreground", "primary-fg"],
  ["secondary", "secondary"],
  ["secondary-foreground", "secondary-fg"],
  ["accent", "accent"],
  ["accent-foreground", "accent-fg"],
  ["destructive", "destructive"],
  ["destructive-foreground", "destructive-fg"],
  ["success", "success"],
  ["warning", "warning"],
];

// Default line height per text size (used in the Tailwind theme).
const TEXT_LINE_HEIGHTS = {
  xs: "normal",
  sm: "normal",
  base: "normal",
  lg: "normal",
  xl: "snug",
  "2xl": "snug",
  "3xl": "tight",
  "4xl": "tight",
};

export function toKebab(path) {
  return path
    .split(".")
    .map((segment) => segment.replace(/[A-Z]/g, (c) => `-${c.toLowerCase()}`))
    .join("-");
}

export function flattenTokens(node, prefix = "", out = {}) {
  for (const [key, value] of Object.entries(node)) {
    if (key.startsWith("$")) continue;
    const path = prefix ? `${prefix}.${key}` : key;
    if (value !== null && typeof value === "object" && !Array.isArray(value)) {
      if ("$value" in value) out[path] = { $type: value.$type, $value: value.$value };
      else flattenTokens(value, path, out);
    } else {
      out[path] = { $type: undefined, $value: value };
    }
  }
  return out;
}

const ALIAS_RE = /^\{([a-zA-Z0-9._-]+)\}$/;

export function resolveValue(values, path, stack = new Set()) {
  if (!(path in values)) throw new Error(`Unknown token reference: {${path}}`);
  if (stack.has(path)) throw new Error(`Circular token reference at {${path}}`);
  const value = values[path].$value;
  if (typeof value === "string") {
    const match = value.match(ALIAS_RE);
    if (match) return resolveValue(values, match[1], new Set(stack).add(path));
  }
  return value;
}

export function renderShadow(shadows) {
  return shadows.map((s) => `${s.x}px ${s.y}px ${s.blur}px ${s.spread ?? 0}px ${s.color}`).join(", ");
}

export function renderCubicBezier([x1, y1, x2, y2]) {
  return `cubic-bezier(${x1}, ${y1}, ${x2}, ${y2})`;
}

const GENERIC_FONTS = new Set([
  "serif", "sans-serif", "monospace", "cursive", "fantasy", "system-ui",
  "ui-serif", "ui-sans-serif", "ui-monospace", "ui-rounded",
]);

export function renderFontFamily(families) {
  return families
    .map((f) => (GENERIC_FONTS.has(f) || f.startsWith("-") ? f : `"${f}"`))
    .join(", ");
}

export function renderValue(type, value) {
  switch (type) {
    case "color": return value;
    case "dimension": return value;
    case "number": return String(value);
    case "fontWeight": return String(value);
    case "fontFamily": return renderFontFamily(value);
    case "shadow": return renderShadow(value);
    case "duration": return value;
    case "cubicBezier": return renderCubicBezier(value);
    default: throw new Error(`Unsupported token $type: ${type}`);
  }
}

function readJson(path) {
  return JSON.parse(readFileSync(path, "utf8"));
}

function buildPrimitivesCss(primitives) {
  const flat = flattenTokens(primitives);
  const lines = [];
  for (const [path, entry] of Object.entries(flat)) {
    const value = resolveValue(flat, path);
    lines.push(`  --ds-${toKebab(path)}: ${renderValue(entry.$type, value)};`);
  }
  return lines.join("\n");
}

function buildSemanticBlock(semantic, primitivesFlat, indent = "  ") {
  const flat = flattenTokens(semantic);
  const lines = [];
  for (const [key, entry] of Object.entries(flat)) {
    if (typeof entry.$value !== "string" || !ALIAS_RE.test(entry.$value)) {
      throw new Error(`Semantic token "${key}" must reference a primitive token, got: ${JSON.stringify(entry.$value)}`);
    }
    const refPath = entry.$value.slice(1, -1);
    const value = resolveValue(primitivesFlat, refPath);
    lines.push(`${indent}--ds-${toKebab(key)}: ${renderValue(entry.$type, value)};`);
  }
  return lines.join("\n");
}

export function buildTokensCss(primitives, light, dark) {
  return `${HEADER}:root {
${buildPrimitivesCss(primitives)}

${buildSemanticBlock(light, flattenTokens(primitives))}
}

.dark {
${buildSemanticBlock(dark, flattenTokens(primitives))}
}
`;
}

export function buildTailwindTheme(primitives, light) {
  const lines = [];

  const flat = flattenTokens(primitives);
  for (const path of Object.keys(flat)) {
    const [group] = path.split(".");
    const cssVar = `var(--ds-${toKebab(path)})`;
    if (group === "color") {
      lines.push(`  --color-${toKebab(path.replace("color.", ""))}: ${cssVar};`);
    } else if (group === "radius" || group === "shadow" || group === "font" || group === "fontWeight") {
      lines.push(`  --${toKebab(path)}: ${cssVar};`);
    } else if (group === "fontSize") {
      const size = path.replace("fontSize.", "");
      lines.push(`  --text-${size}: ${cssVar};`);
      lines.push(`  --text-${size}--line-height: var(--ds-line-height-${TEXT_LINE_HEIGHTS[size]});`);
    } else if (group === "lineHeight") {
      lines.push(`  --leading-${path.replace("lineHeight.", "")}: ${cssVar};`);
    } else if (group === "easing") {
      lines.push(`  --ease-${path.replace("easing.", "")}: ${cssVar};`);
    }
    // space.* and duration.* are not Tailwind namespaces; use --ds-* directly.
  }

  const semanticLines = SEMANTIC_COLORS.map(
    ([twName, key]) => `  --color-${twName}: var(--ds-${key});`,
  );

  return `${HEADER}@theme inline {
${[...lines, ...semanticLines].join("\n")}
}
`;
}

export function buildDesignMdSection(primitives, light, dark) {
  const primitivesFlat = flattenTokens(primitives);
  const lightFlat = flattenTokens(light);
  const darkFlat = flattenTokens(dark);

  const rows = Object.keys(lightFlat).map((key) => {
    const lightValue = resolveValue(primitivesFlat, lightFlat[key].$value.slice(1, -1));
    const darkValue = resolveValue(primitivesFlat, darkFlat[key].$value.slice(1, -1));
    return `| \`--ds-${key}\` | \`${lightValue}\` | \`${darkValue}\` | \`${lightFlat[key].$value}\` |`;
  });

  const colorCount = Object.keys(flattenTokens(primitives.color ?? {})).length;
  const scaleCount = Object.keys(primitivesFlat).length - colorCount;

  return [
    "<!-- tokens:begin -->",
    "<!-- AUTO-GENERATED by scripts/build-tokens.mjs — do not edit. Source: tokens/ -->",
    "",
    `### Semantic color tokens (${Object.keys(lightFlat).length})`,
    "",
    "Light and dark themes. In Tailwind these are exposed as utilities",
    "(`bg-primary`, `text-muted-foreground`, `border-border`, …).",
    "",
    "| CSS variable | Light | Dark | References |",
    "| ------------ | ----- | ---- | ---------- |",
    ...rows,
    "",
    "### Primitive scales",
    "",
    `- ${colorCount} primitive color steps across 5 hues (neutral, blue, green, amber, red)`,
    `- ${scaleCount} primitive values for spacing, radius, typography, shadows, motion`,
    "- Full source: [`tokens/primitives.json`](tokens/primitives.json) (DTCG format)",
    "",
    "<!-- tokens:end -->",
  ].join("\n");
}

export function updateDesignMd(section) {
  if (!existsSync(DESIGN_MD)) return false;
  const content = readFileSync(DESIGN_MD, "utf8");
  const begin = content.indexOf("<!-- tokens:begin -->");
  const end = content.indexOf("<!-- tokens:end -->");
  if (begin === -1 || end === -1) return false;
  const updated = content.slice(0, begin) + section + content.slice(end + "<!-- tokens:end -->".length);
  writeFileSync(DESIGN_MD, updated);
  return true;
}

function main() {
  const primitives = readJson(join(TOKENS_DIR, "primitives.json"));
  const light = readJson(join(TOKENS_DIR, "semantic", "light.json"));
  const dark = readJson(join(TOKENS_DIR, "semantic", "dark.json"));

  mkdirSync(DIST_DIR, { recursive: true });
  writeFileSync(join(DIST_DIR, "tokens.css"), buildTokensCss(primitives, light, dark));
  writeFileSync(join(DIST_DIR, "tailwind-theme.css"), buildTailwindTheme(primitives, light));
  const designUpdated = updateDesignMd(buildDesignMdSection(primitives, light, dark));

  console.log("Built dist/tokens.css, dist/tailwind-theme.css" + (designUpdated ? ", DESIGN.md tokens section" : ""));
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  main();
}
